# frozen_string_literal: true

module Security
  module SecretDetection
    module PartnerTokens
      # Auto-generated by ClientGenerator from a reviewed VendorDefinition.
      # Vendor docs: https://developer.gocardless.com/api-reference/#creditors-list-creditors
      # Regenerate rather than hand-editing; keep the VendorDefinition as the source of truth.
      class GocardlessClient < BaseClient
        API_ENDPOINT = "https://api.gocardless.com/creditors"

        private

        def partner_name
          "gocardless"
        end

        def verify_partner_token(token_value)
          response = make_request(
            API_ENDPOINT,
            method: :get,
            headers: {
              'Authorization' => "Bearer #{token_value}",
              "GoCardless-Version" => "2015-07-06",
              'Accept' => 'application/json'
            }
          )
          analyze_response(response)
        end

        def analyze_response(response)
          case response.code.to_i
          when 200, 403
            token_response(:active)
          when 401
            token_response(:inactive)
          when 429
            raise RateLimitError, "gocardless rate limited: #{response.code}"
          when 500, 502, 503, 504
            raise NetworkError, "gocardless service error: #{response.code}"
          else
            # unknown-never-inactive: unmapped codes are never treated as dead tokens.
            token_response(:unknown)
          end
        end
      end
    end
  end
end
